mapper.select:
select aa.address_id as addressId, aa.account_id as accountId, aa.receiver_name as receiverName, aa.receiver_phone as receiverPhone, aa.province as province, aa.city as city, aa.district as district, aa.detail_address as detailAddress, aa.postal_code as postalCode, aa.is_default as isDefault, aa.del_flag as delFlag, aa.create_time as createTime, aa.update_time as updateTime, aa.remark as remark from account_address aa where aa.del_flag = 0
and aa.account_id = #{accountId}
and aa.receiver_name like concat('%', #{receiverName}, '%')
and aa.receiver_phone like concat('%', #{receiverPhone}, '%')
and aa.is_default = #{isDefault}
order by aa.address_id desc

select count(1) from account_address aa where aa.del_flag = 0
and aa.account_id = #{accountId}
and aa.receiver_name like concat('%', #{receiverName}, '%')
and aa.receiver_phone like concat('%', #{receiverPhone}, '%')
and aa.is_default = #{isDefault}

select aa.address_id, aa.account_id, aa.receiver_name, aa.receiver_phone, aa.province, aa.city, aa.district, aa.detail_address, aa.postal_code, aa.is_default, aa.del_flag, aa.create_time, aa.update_time, aa.remark from account_address aa where aa.del_flag = 0
and aa.account_id = #{accountId}
and aa.receiver_name like concat('%', #{receiverName}, '%')
and aa.receiver_phone like concat('%', #{receiverPhone}, '%')
and aa.is_default = #{isDefault}
order by aa.address_id desc limit 1

